```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

export function spinAround(camera: ArcRotateCamera, scene: SceneContext, turns: number): Promise<void> {
  if (!Number.isFinite(turns) || turns === 0) {
    return Promise.resolve();
  }

  const startAlpha = camera.alpha;
  const targetAlpha = startAlpha + Math.PI * 2 * turns;

  return interpolateArcRotateCamera(camera, scene, { alpha: targetAlpha }).then(() => {
    camera.alpha = targetAlpha;
  });
}
```

I wrote `src/turntable.ts` to use the library’s `interpolateArcRotateCamera` transition to animate only `alpha` to `start + 2π·turns`, then snap `alpha` to the exact target when the transition resolves. I’m not sure whether your camera has restrictive alpha limits; if it does, they could clamp the target and prevent the exact final `alpha`.
